function testCategory(name, observations) {
  console.log(`\n=== ${name} Test (${observations.length} observations) ===\n`);

  const factorCounts = {};
  let noFactors = 0;
  const failures = [];

  observations.forEach((obs, i) => {
    const factors = detectContributingFactors(obs);

    if (factors.length === 0) {
      noFactors++;
      failures.push({ num: i + 1, obs: obs.substring(0, 80) });
    }

    factors.forEach(f => {
      factorCounts[f] = (factorCounts[f] || 0) + 1;
    });
  });

  console.log('=== FACTOR BREAKDOWN ===');
  const sortedFactors = Object.entries(factorCounts).sort((a, b) => b[1] - a[1]);
  sortedFactors.forEach(([factor, count]) => {
    console.log(`${factor}: ${count} (${Math.round(count/observations.length*100)}%)`);
  });

  console.log('\n=== SUMMARY ===');
  console.log('Total observations:', observations.length);
  console.log('Observations with factors:', observations.length - noFactors, '(' + Math.round((observations.length - noFactors)/observations.length*100) + '%)');
  console.log('Still unclassified:', noFactors);

  if (failures.length > 0 && failures.length <= 25) {
    console.log('\n=== STILL UNCLASSIFIED (' + failures.length + ') ===');
    failures.forEach(f => {
      console.log(f.num + '. "' + f.obs + '..."');
    });
  }

  return { total: observations.length, classified: observations.length - noFactors, unclassified: noFactors };
}

// Run tests
const bbsResults = testCategory('BBS Observations in Site Security', bbsObservations);
const signageResults = testCategory('Signage Observations in Site Security', signageObservations);
const maintenanceResults = testCategory('Maintenance Observations in Site Security', maintenanceObservations);

// Combined summary
console.log('\n\n========== COMBINED SUMMARY ==========');
const totalObs = bbsResults.total + signageResults.total + maintenanceResults.total;
const totalClassified = bbsResults.classified + signageResults.classified + maintenanceResults.classified;
console.log(`Total Site Security observations: ${totalObs}`);
console.log(`Total classified: ${totalClassified} (${Math.round(totalClassified/totalObs*100)}%)`);
console.log(`Total unclassified: ${totalObs - totalClassified}`);
